namespace VinsPDF {
internal sealed partial class MainForm {
 TextBox inlineText;EditObject inlineObject;PointF inlinePosition;string inlineOriginal;Font inlineFont;
 void BeginInline(EditObject obj){if(sizes==null||editBusy||!canvas.Editing||(obj!=null&&obj.Kind!=1))return;if(!FinishInline())return;ShowPalette();inlineObject=obj;inlineOriginal=obj==null?"":obj.Text;inlinePosition=obj==null?canvas.Normalized(new Point(canvas.Width/2,canvas.Height/2)):new PointF(obj.BaselineX,obj.BaselineY);if(obj!=null&&obj.DisplayFontSize>0)textStyle.Size=obj.DisplayFontSize;palette.SetStyle(textStyle);palette.ExpandFont();inlineText=new TextBox{Multiline=true,AcceptsReturn=true,AcceptsTab=true,Text=inlineOriginal,BackColor=Color.White,ForeColor=obj==null?Color.Black:Color.FromArgb((int)obj.Color),BorderStyle=BorderStyle.FixedSingle,ScrollBars=ScrollBars.Vertical};canvas.Controls.Add(inlineText);canvas.InlineActive=true;UpdateInlineFont();inlineText.TextChanged+=delegate{LayoutInline();};inlineText.Focus();inlineText.SelectAll();status.Text="Edit text on page · Ctrl+Enter applies · Esc cancels · Font settings on the right";}
 void LayoutInline(){if(inlineText==null)return;Rectangle p=canvas.PageRectangle;float x=inlineObject==null?inlinePosition.X:inlineObject.Bounds.X,y=inlineObject==null?inlinePosition.Y-textStyle.Size/canvas.PageSize.Height:inlineObject.Bounds.Top;int left=p.X+(int)(x*p.Width),top=p.Y+(int)(y*p.Height);int width=inlineObject==null?260:(int)(inlineObject.Bounds.Width*p.Width)+16;int lines=Math.Max(1,inlineText.Lines.Length);int height=Math.Max(42,(int)(textStyle.Size*canvas.Scale*(lines+1)*1.3));inlineText.SetBounds(Math.Max(0,Math.Min(canvas.Width-100,left)),Math.Max(0,Math.Min(canvas.Height-45,top)),Math.Max(100,Math.Min(Math.Max(180,width),canvas.Width-Math.Max(0,left)-8)),Math.Min(Math.Max(45,height),Math.Max(45,canvas.Height-Math.Max(0,top)-8)));}
 void UpdateInlineFont(){if(inlineText==null)return;var old=inlineFont;inlineFont=new Font(textStyle.Family,(float)Math.Max(5,Math.Min(180,textStyle.Size*canvas.Scale)),(textStyle.Bold?FontStyle.Bold:FontStyle.Regular)|(textStyle.Italic?FontStyle.Italic:FontStyle.Regular),GraphicsUnit.Pixel);inlineText.Font=inlineFont;if(old!=null)old.Dispose();LayoutInline();}
 void CancelInline(){if(inlineText==null)return;canvas.Controls.Remove(inlineText);inlineText.Dispose();inlineText=null;inlineObject=null;canvas.InlineActive=false;if(inlineFont!=null){inlineFont.Dispose();inlineFont=null;}canvas.Focus();}
 void CommitInline(){if(inlineText==null)return;string value=inlineText.Text;if(string.IsNullOrWhiteSpace(value)){status.Text="Enter text, or cancel and use Delete selection.";return;}EditObject obj=inlineObject;PointF position=inlinePosition;TextStyle style=textStyle.Copy();int[] ids=obj==null?new int[0]:obj.Ids;CancelInline();ApplyEdit(delegate(PdfEngine e){return e.PutTextBlock(pageIndex,ids,value,style,position,obj==null?0:obj.Angle);});}
 bool FinishInline(){if(inlineText==null)return true;status.Text="Apply text with Ctrl+Enter, or cancel with Esc, before this action.";return false;}
 bool InlineKey(Keys key){if(inlineText==null)return false;if(key==(Keys.Control|Keys.Enter)){CommitInline();return true;}if(key==Keys.Escape){CancelInline();return true;}return false;}
 void RotateSelected(float degrees){var obj=canvas.CombinedSelection();if(obj==null||editBusy)return;ApplyEdit(delegate(PdfEngine e){e.RotateObjects(pageIndex,obj.Ids,obj.Bounds,degrees);return obj.Id;},obj.Ids);}
}
internal sealed partial class PdfEngine {
 public void RotateObjects(int index,int[] ids,RectangleF bounds,float degrees){PointF center=ToPdf(Page(index),bounds.Left+bounds.Width/2,bounds.Top+bounds.Height/2);double angle=-degrees*Math.PI/180,c=Math.Cos(angle),s=Math.Sin(angle);Batch(index,delegate{foreach(int id in ids.Distinct()){IntPtr obj=ObjectAt(index,id);Native.Matrix old;Check(Native.FPDFPageObj_GetMatrix(obj,out old)!=0,"Could not read object transform.");var next=new Native.Matrix{A=(float)(c*old.A-s*old.B),B=(float)(s*old.A+c*old.B),C=(float)(c*old.C-s*old.D),D=(float)(s*old.C+c*old.D),E=(float)(center.X+c*(old.E-center.X)-s*(old.F-center.Y)),F=(float)(center.Y+s*(old.E-center.X)+c*(old.F-center.Y))};Commit(index,delegate{SetObjectMatrix(obj,old);},delegate{SetObjectMatrix(obj,next);});}});}
}
}
